entries[246982] = { ["name"] = "Glyphe 'Funkensplitter'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)\nStellt eine Glyphe 'Funkensplitter' her.\nBeute von:\nKil'jaeden\nZone:\nDas Grabmal des Sargeras\n\nSchatz:\nBeutetruhe des Falls der Legion\nZone:\nAzsuna\n\nKlassen: Hexenmeister\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nAls Zerstörungshexenmeister können Eure Seelensplitter in instabile Funken eingeschlossen sein, die über Eurem Kopf schweben. Exklusiv mit: Glyphe 'Schwebende Splitter' Glyphe 'Teufelsberührte Splitter'\n11" }
